    // Insert element at the front
    void insertFront(int x) {
        if (size == capacity) {
            cout << "Deque is full\n";
            return;
        }

        front = (front - 1 + capacity) % capacity;
        arr[front] = x;

        size++;
    }

    // Insert element at the rear
    void insertRear(int x) {
        if (size == capacity) {
            cout << "Deque is full\n";
            return;
